// Generated by Cypress Author on 2026-10-30.
import { call, callRefused } from "../../../../support/odoo";

const LOGIN = "demo.unlinked";

// Puts demo.unlinked back among the unlinked users when an earlier run linked it; its employee stays.
function unlinkDemoUser() {
  call("medilab.person", "search", [[["user_id.login", "=", LOGIN]]], { context: { active_test: false } }).then(
    (ids) => {
      if (ids.length) {
        call("medilab.person", "unlink", [ids]);
      }
    },
  );
}

describe("Internal users only through people", () => {
  beforeEach(() => {
    cy.signInAs("administrator");
    unlinkDemoUser();
  });

  it("links an unlinked user to a new person → the user leaves the list and signs in as the person", () => {
    cy.visit("/odoo/unlinked-users");
    // The demo administrator may read the screen in Vietnamese, so the row's only button is found by its place.
    cy.contains(".o_data_row", LOGIN).find("td.o_list_button button").should("have.length", 1).click();

    // An empty person creates one from the user.
    cy.get(".modal:visible").within(() => {
      cy.get('[name="user_id"]').should("contain.text", "Trinh Van Hung");
      cy.get('button[name="action_link"]').click();
    });

    cy.get(".o_form_view").should("be.visible");
    cy.get('.o_form_view [name="login"] input').should("have.value", LOGIN);
    call("res.users", "search_count", [[["login", "=", LOGIN], ["has_person", "=", true]]]).should("eq", 1);

    cy.visit("/odoo/unlinked-users");
    cy.get(".o_list_view").should("be.visible");
    cy.contains(".o_data_row", LOGIN).should("not.exist");
  });

  it("creates an internal user outside a person → refused, and the Users screen offers no New", () => {
    callRefused("res.users", "create", [{ login: "demo.outside", name: "Ngo Van Tam" }]).should(
      "contain",
      "only through a person",
    );

    cy.visit("/odoo/users");
    cy.get(".o_list_view").should("be.visible");
    cy.get(".o_list_button_add").should("not.exist");
  });
});
